// site_step and gate_template row-level security and integrity — generated by `pnpm gen:migration`
// (02-architecture §4, 04-testing §3); E3 (SOP-DEL-04) cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  createDatabase,
  eq,
  gateTemplate,
  inActorTransaction,
  migrateUp,
  site,
  siteStep,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const siteA = randomUUID();
const siteB = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const userOfB: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientB] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const siteOf = (id: string, clientId: string, projectId: string) => ({
  id,
  clientId,
  projectId,
  countryCode: 'ES',
  cityCode: 'MAD',
  cityName: 'Madrid',
  runningNo: 1,
  name: 'Site 001',
  standard: 'S' as const,
});
const stepOf = (
  clientId: string,
  siteId: string,
  step: string,
  more: Partial<typeof siteStep.$inferInsert> = {},
) => ({
  id: randomUUID(),
  clientId,
  siteId,
  step,
  doneOn: '2026-11-10',
  actorId: staff.id,
  ...more,
});
let testDb: TestDatabase;
let database: Database;

type Tx = Parameters<Parameters<typeof inActorTransaction>[2]>[0];
const asStaff = <T>(work: (tx: Tx) => Promise<T>) => inActorTransaction(database.db, staff, work);
const stepsSeenBy = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) =>
    (await tx.select().from(siteStep)).map((r) => r.step).sort(),
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await asStaff(async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx
      .insert(site)
      .values([siteOf(siteA, clientA, 'CLIENTA-ES-MAD-001'), siteOf(siteB, clientB, 'CLIENTB-ES-MAD-001')]);
    await tx
      .insert(siteStep)
      .values([
        stepOf(clientA, siteA, 'card_received', { visibility: 'client' }),
        stepOf(clientA, siteA, 'card_complete'),
        stepOf(clientB, siteB, 'card_received'),
      ]);
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see every step; a client only its own steps marked for clients; partners nothing', async () => {
  expect(await stepsSeenBy(staff)).toEqual(['card_complete', 'card_received', 'card_received']);
  expect(await stepsSeenBy(userOfA)).toEqual(['card_received']);
  expect(await stepsSeenBy(userOfB)).toEqual([]);
  expect(await stepsSeenBy(partnerOfA)).toEqual([]);
});

it('a client cannot write', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) =>
      tx.insert(siteStep).values(stepOf(clientA, siteA, 'installed')),
    ),
  ).rejects.toThrow();
});

it('a step belongs to a project of its own client, has a key-like name, and is reached once while active', async () => {
  for (const bad of [stepOf(clientA, siteB, 'installed'), stepOf(clientA, siteA, 'Not A Key')]) {
    await expect(asStaff((tx) => tx.insert(siteStep).values(bad))).rejects.toThrow();
  }
  await expect(
    asStaff((tx) => tx.insert(siteStep).values(stepOf(clientA, siteA, 'card_complete'))),
  ).rejects.toThrow();
});

it('a step is never edited, only archived — and then it can be recorded again', async () => {
  await expect(
    asStaff((tx) =>
      tx.update(siteStep).set({ doneOn: '2026-11-11' }).where(eq(siteStep.step, 'card_complete')),
    ),
  ).rejects.toThrow();
  await asStaff((tx) =>
    tx.update(siteStep).set({ archivedAt: new Date() }).where(eq(siteStep.step, 'card_complete')),
  );
  await asStaff((tx) =>
    tx.insert(siteStep).values(stepOf(clientA, siteA, 'card_complete', { doneOn: '2026-11-11' })),
  );
});

it('a gate template is internal configuration: staff only, gates as a non-empty list', async () => {
  const template = {
    id: randomUUID(),
    clientId: clientA,
    name: 'Client A gates',
    gates: [{ key: 'g1', name: 'Go/no-go', order: 1 }],
  };
  await asStaff((tx) => tx.insert(gateTemplate).values(template));
  await expect(
    asStaff((tx) => tx.insert(gateTemplate).values({ ...template, id: randomUUID(), gates: [] })),
  ).rejects.toThrow();
  const seen = (actor: DbActor) =>
    inActorTransaction(database.db, actor, async (tx) => (await tx.select().from(gateTemplate)).length);
  expect([await seen(staff), await seen(userOfA)]).toEqual([1, 0]);
  await asStaff((tx) =>
    tx
      .update(site)
      .set({ gateTemplateId: template.id, plannedInstallationDate: '2026-12-01' })
      .where(eq(site.id, siteA)),
  );
});
